const leads = $input.all().map(i => i.json);
if (!leads.length || !leads[0].id) return [];

// Sales team configuration
const salesTeam = [
  { name: 'Sales Rep A', email: 'repa@company.com', territories: ['jakarta', 'jabodetabek'], specialties: ['enterprise'], max_active_deals: 15 },
  { name: 'Sales Rep B', email: 'repb@company.com', territories: ['surabaya', 'jawa_timur'], specialties: ['smb', 'startup'], max_active_deals: 20 },
  { name: 'Sales Rep C', email: 'repc@company.com', territories: ['bandung', 'jawa_barat'], specialties: ['smb'], max_active_deals: 20 },
  { name: 'Sales Rep D', email: 'repd@company.com', territories: ['all'], specialties: ['all'], max_active_deals: 25 }
];

// Round-robin counter (simplified - in production use Redis)
let roundRobinIndex = Math.floor(Math.random() * salesTeam.length);

const results = [];

for (const lead of leads) {
  const territory = (lead.custom_fields?.city || lead.custom_fields?.region || 'all').toLowerCase();
  const companySize = lead.custom_fields?.company_size || '';
  const isEnterprise = companySize.includes('500') || companySize.includes('1000') || lead.lead_score >= 80;
  const specialty = isEnterprise ? 'enterprise' : 'smb';

  // Find best match by territory + specialty
  let assignedRep = null;

  // Priority 1: Territory + Specialty match
  assignedRep = salesTeam.find(rep => 
    (rep.territories.includes(territory) || rep.territories.includes('all')) &&
    (rep.specialties.includes(specialty) || rep.specialties.includes('all'))
  );

  // Priority 2: Territory match only
  if (!assignedRep) {
    assignedRep = salesTeam.find(rep => 
      rep.territories.includes(territory) || rep.territories.includes('all')
    );
  }

  // Priority 3: Round-robin fallback
  if (!assignedRep) {
    assignedRep = salesTeam[roundRobinIndex % salesTeam.length];
    roundRobinIndex++;
  }

  results.push({
    json: {
      contact_id: lead.id,
      email: lead.email,
      contact_name: `${lead.first_name} ${lead.last_name}`,
      company: lead.company,
      lead_score: lead.lead_score,
      assigned_to: assignedRep.name,
      assigned_email: assignedRep.email,
      assignment_reason: `Territory: ${territory}, Specialty: ${specialty}`,
      client_id: lead.client_id
    }
  });
}

return results;

